def compute(inputs):
    principal = inputs['principal']
    interest_rate = inputs['interest_rate']
    periods = int(inputs['periods'])
    if interest_rate == 0:
        payout = principal / periods
    else:
        payout = principal * (interest_rate * (1 + interest_rate) ** periods) / ((1 + interest_rate) ** periods - 1)
    return payout

def compute(inputs):
    current_eps = inputs['current_eps']
    previous_eps = inputs['previous_eps']
    growth_rate = (current_eps / previous_eps - 1) * 100
    return round(growth_rate, 2)
